import { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import type { GroupedPermissions, PermissionItem, RoleRow } from '../types/roles.types';
import { useHasPermission } from '../hooks/usePermission';

const RoleFormPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const isEdit = Boolean(id);
    const canSave = useHasPermission(isEdit ? 'edit_role' : 'create_role');
    const canLoadPermissions = useHasPermission('list_permission');

    const [name, setName] = useState('');
    const [isActive, setIsActive] = useState(true);
    const [groups, setGroups] = useState<GroupedPermissions>({});
    const [selectedIds, setSelectedIds] = useState<number[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            if (isEdit && id) {
                const res = await apiGet<{ data: { permissions: GroupedPermissions; role: RoleRow | null } }>({
                    endpoint: `${endpoints.accessControl.rolePermissions}${id}`,
                });
                const payload = res.data?.data;
                setGroups(payload?.permissions ?? {});
                const role = payload?.role;
                if (role) {
                    setName(role.name ?? '');
                    setIsActive(role.is_active === 1 || role.is_active === true);
                    const ids = (role.permissions ?? []).map((p) => p.id).filter(Boolean);
                    setSelectedIds(ids);
                }
            } else {
                const res = await apiGet<{ data: GroupedPermissions }>({ endpoint: endpoints.accessControl.permissionList });
                setGroups(res.data?.data ?? {});
                setSelectedIds([]);
                setName('');
                setIsActive(true);
            }
        } catch {
            toast.error('تعذر تحميل البيانات');
        } finally {
            setLoading(false);
        }
    }, [id, isEdit]);

    useEffect(() => {
        if (canLoadPermissions) {
            load();
        } else {
            setLoading(false);
        }
    }, [load, canLoadPermissions]);

    const togglePermission = (permId: number) => {
        setSelectedIds((prev) => (prev.includes(permId) ? prev.filter((x) => x !== permId) : [...prev, permId]));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!canSave) {
            toast.error('ليس لديك صلاحية');
            return;
        }
        if (!name.trim()) {
            toast.error('اسم الدور مطلوب');
            return;
        }
        setSaving(true);
        try {
            const body = {
                name: name.trim().toLowerCase(),
                is_active: isActive ? 1 : 0,
                permissions: selectedIds,
            };
            if (isEdit && id) {
                await apiPost({
                    endpoint: `${endpoints.accessControl.roleUpdate}${id}`,
                    body: { ...body, id },
                });
                toast.success('تم تحديث الدور');
            } else {
                await apiPost({
                    endpoint: endpoints.accessControl.roleCreate,
                    body,
                });
                toast.success('تم إنشاء الدور');
            }
            navigate('/access-control/roles');
        } catch (err: unknown) {
            const msg =
                err && typeof err === 'object' && 'response' in err
                    ? (err as { response?: { data?: { msg?: string } } }).response?.data?.msg
                    : null;
            toast.error(msg || 'فشل الحفظ');
        } finally {
            setSaving(false);
        }
    };

    if (!canLoadPermissions) {
        return <p className="mt-8 px-2 text-sm text-white-blue-700">ليس لديك صلاحية عرض قائمة الصلاحيات.</p>;
    }

    if (loading) {
        return <p className="mt-8 text-sm text-white-blue-700 px-2">جاري التحميل…</p>;
    }

    return (
        <div className="mt-6 w-full max-w-4xl px-2">
            <Link to="/access-control/roles" className="text-sm text-primary hover:underline mb-4 inline-block">
                ← العودة لقائمة الأدوار
            </Link>
            <UnderlineHeading text={isEdit ? 'تعديل دور' : 'إضافة دور'} />
            <form onSubmit={handleSubmit} className="mt-6 space-y-6 rounded-lg border border-[#E8E7EA] p-6 shadow-sm">
                <div>
                    <label className="text-sm font-medium text-primery-blue-500 block mb-2">اسم الدور</label>
                    <Input value={name} onChange={(e) => setName(e.target.value)} className="max-w-md" dir="ltr" />
                </div>
                <label className="flex items-center gap-2 text-sm">
                    <input type="checkbox" checked={isActive} onChange={(e) => setIsActive(e.target.checked)} />
                    الدور مفعّل
                </label>
                <div>
                    <h3 className="text-base font-semibold text-primery-blue-500 mb-3">الصلاحيات</h3>
                    <div className="space-y-6 max-h-[480px] overflow-y-auto pe-2">
                        {Object.entries(groups).map(([groub, items]) => (
                            <section key={groub}>
                                <h4 className="text-sm font-semibold text-white-blue-800 mb-2">{groub}</h4>
                                <div className="grid gap-2 sm:grid-cols-2">
                                    {(items as PermissionItem[]).map((p) => (
                                        <label key={p.id} className="flex items-center gap-2 text-sm cursor-pointer">
                                            <input
                                                type="checkbox"
                                                checked={selectedIds.includes(p.id)}
                                                onChange={() => togglePermission(p.id)}
                                            />
                                            <span className="font-mono text-xs">{p.name}</span>
                                        </label>
                                    ))}
                                </div>
                            </section>
                        ))}
                    </div>
                </div>
                <PrimaryButton type="submit" disabled={saving || !canSave}>
                    {saving ? 'جاري الحفظ…' : 'حفظ'}
                </PrimaryButton>
            </form>
        </div>
    );
};

export default RoleFormPage;
